svg.script:

let animationsPaused = false;
let animationSpeed = 1;

document.addEventListener('keydown', function(event) {
  const svg = document.querySelector('svg');

  if (event.key === ' ') {
    event.preventDefault();
    toggleAnimations(svg);
  } else if (event.key === '+' || event.key === '=') {
    event.preventDefault();
    changeSpeed(0.1, svg);
  } else if (event.key === '-' || event.key === '_') {
    event.preventDefault();
    changeSpeed(-0.1, svg);
  } else if (event.key.toLowerCase() === 'r') {
    event.preventDefault();
    resetAnimations(svg);
  } else if (event.key === '0') {
    event.preventDefault();
    normalizeSpeed(svg);
  }

  updateInfoText(svg);
});

function toggleAnimations(svg) {
  animationsPaused = !animationsPaused;
  const elements = svg.querySelectorAll('[class*="spinning-"], [class*="bouncing-"], [class*="sliding-"], [class*="color-"]');
  elements.forEach(el => {
    if (animationsPaused) {
      el.classList.add('paused');
    } else {
      el.classList.remove('paused');
    }
  });
}

function changeSpeed(delta, svg) {
  animationSpeed = Math.max(0.1, animationSpeed + delta);
  applySpeed(svg);
}

function normalizeSpeed(svg) {
  animationSpeed = 1;
  applySpeed(svg);
}

function applySpeed(svg) {
  const elements = svg.querySelectorAll('[class*="spinning-"], [class*="bouncing-"], [class*="sliding-"], [class*="color-"]');
  elements.forEach(el => {
    const styles = window.getComputedStyle(el);
    const animationDuration = styles.animationDuration;
    el.style.animationPlayState = animationsPaused ? 'paused' : 'running';
  });

  svg.style.setProperty('--speed', animationSpeed);
  svg.querySelectorAll('style')[0].sheet.cssRules[0].style.animationDuration = (3 / animationSpeed) + 's';
}

function resetAnimations(svg) {
  const elements = svg.querySelectorAll('[class*="spinning-"], [class*="bouncing-"], [class*="sliding-"], [class*="color-"]');
  elements.forEach(el => {
    el.style.animation = 'none';
    setTimeout(() => {
      el.style.animation = '';
    }, 10);
  });
}

function updateInfoText(svg) {
  const infoEl = svg.querySelector('#info-display');
  if (infoEl) {
    let status = `Speed: ${animationSpeed.toFixed(1)}x | Status: ${animationsPaused ? 'PAUSED' : 'RUNNING'}`;
    infoEl.textContent = status;
  }
}

window.addEventListener('load', function() {
  const svg = document.querySelector('svg');
  updateInfoText(svg);
});
